  let filters = { month: 'all', category: 'all' };

  // ---------- Helpers ----------
  const generateId = () => crypto.randomUUID?.() ?? `${Date.now()}-${Math.random().toString(36).slice(2, 11)}`;

  const parseISO = (str) => {
    const d = new Date(str + 'T00:00:00');
    return isNaN(d) ? null : d;
  };

  const formatDate = (date) => date.toISOString().split('T')[0];

  const todayISO = () => formatDate(new Date());

  const getMonthKey = (dateStr) => dateStr.slice(0, 7); // YYYY‑MM

  const round2 = (n) => Math.round(n * 100) / 100;

  // ---------- Persistence ----------
  function loadTransactions() {
    try {
      const raw = localStorage.getItem(STORAGE_KEY);
      transactions = raw ? JSON.parse(raw) : [];
      transactions.forEach(t => { t.amount = Number(t.amount); });
    } catch (e) { console.error('Failed to load transactions:', e); transactions = []; }
  }
  function saveTransactions() { try { localStorage.setItem(STORAGE_KEY, JSON.stringify(transactions)); } catch (e) { console.error('Failed to save transactions:', e); } }

  function loadFilters() {
    try {
      const raw = localStorage.getItem(FILTERS_KEY);
      filters = raw ? JSON.parse(raw) : { month: 'all', category: 'all' };
    } catch (e) { filters = { month: 'all', category: 'all' }; }
  }
  function saveFilters() { try { localStorage.setItem(FILTERS_KEY, JSON.stringify(filters)); } catch (e) { console.error('Failed to save filters:', e); } }

  // ---------- Validation ----------
  function validateTransaction(data) {
    const errors = {};
    if (!data.date) { errors.date = 'Date is required'; }
    else {
      const d = parseISO(data.date);
      if (!d) errors.date = 'Invalid date format';
      else if (d > new Date(todayISO() + 'T00:00:00')) errors.date = 'Date cannot be in the future';
    }
    const desc = (data.description || '').trim();
    if (!desc) errors.description = 'Description is required';
    else if (desc.length > 100) errors.description = 'Description must be 100 characters or less';

    const amt = Number(data.amount);
    if (data.amount === '' || data.amount === null || data.amount === undefined) errors.amount = 'Amount is required';
    else if (isNaN(amt) || amt <= 0) errors.amount = 'Amount must be a positive number';
    else if (!/^\d+(\.\d{1,2})?$/.test(String(data.amount).trim())) errors.amount = 'Amount can have at most 2 decimal places';

    if (!data.type || !['income','expense'].includes(data.type)) errors.type = 'Type must be income or expense';
    if (!data.category || !data.category.trim()) errors.category = 'Category is required';

    return {
      valid: Object.keys(errors).length === 0,
      errors,
      sanitized: errors.valid ? {
        date: data.date,
        description: desc,
        amount: round2(amt),
        type: data.type,
        category: data.category.trim()
      } : null
    };
  }

  // ---------- CRUD ----------
  function addTransaction(data) {
    const result = validateTransaction(data);
    if (!result.valid) return { success: false, errors: result.errors };
    const txn = { id: generateId(), ...result.sanitized };
    transactions.push(txn);
    saveTransactions();
    return { success: true, transaction: txn };
  }
  function updateTransaction(id, data) {
    const idx = transactions.findIndex(t => t.id === id);
    if (idx === -1) return { success: false, errors: { form: 'Transaction not found' } };
    const result = validateTransaction(data);
    if (!result.valid) return { success: false, errors: result.errors };
    transactions[idx] = { id, ...result.sanitized };
    saveTransactions();
    return { success: true, transaction: transactions[idx] };
  }
  function deleteTransaction(id) {
    const idx = transactions.findIndex(t => t.id === id);
    if (idx === -1) return { success: false };
    transactions.splice(idx, 1);
    saveTransactions();
    return { success: true };
  }
  function getTransaction(id) { return transactions.find(t => t.id === id) || null; }
  function getAllTransactions() { return [...transactions]; }

  // ---------- Filtering ----------
  function setFilters(newFilters) { filters = { ...filters, ...newFilters }; saveFilters(); }
  function getFilters() { return { ...filters }; }
  function getFilteredTransactions() {
    return transactions.filter(t => {
      const monthMatch = filters.month === 'all' || getMonthKey(t.date) === filters.month;
      const catMatch = filters.category === 'all' || t.category === filters.category;
      return monthMatch && catMatch;
    });
  }
  function getAvailableMonths() {
    const months = new Set(transactions.map(t => getMonthKey(t.date)));
    return Array.from(months).sort().reverse();
  }
  function getAvailableCategories(type) {
    if (type === 'income') return [...CATEGORIES.income];
    if (type === 'expense') return [...CATEGORIES.expense];
    return [...ALL_CATEGORIES];
  }

  // ---------- Calculations ----------
  function calculateSummary(txns = transactions) {
    let income = 0, expenses = 0;
    for (const t of txns) { if (t.type === 'income') income += t.amount; else expenses += t.amount; }
    return { income: round2(income), expenses: round2(expenses), balance: round2(income - expenses) };
  }

  // ---------- Chart Data ----------
  function getChartData() {
    const filtered = getFilteredTransactions();
    const expenses = filtered.filter(t => t.type === 'expense');
    const byCategory = {};
    for (const t of expenses) { byCategory[t.category] = (byCategory[t.category] || 0) + t.amount; }
    const sorted = Object.entries(byCategory)
      .map(([category, total]) => ({ category, total: round2(total) }))
      .sort((a, b) => b.total - a.total);
    const top8 = sorted.slice(0, 8);
    const rest = sorted.slice(8);
    if (rest.length > 0) {
      top8.push({ category: 'Other', total: round2(rest.reduce((sum, r) => sum + r.total, 0)) });
    }
    return top8;
  }

  // ---------- CSV Export ----------
  function escapeCSV(field) {
    const str = String(field);
    if (/[",\n]/.test(str)) { return '"' + str.replace(/"/g, '""') + '"'; }
    return str;
  }
  function exportCSV() {
    const filtered = getFilteredTransactions();
    if (filtered.length === 0) return { success: false, error: 'No transactions to export' };
    const rows = [];
    rows.push(['Date','Description','Amount','Type','Category'].map(escapeCSV).join(','));
    for (const t of filtered) {
      rows.push([t.date, t.description, t.amount.toString(), t.type === 'income' ? 'Income' : 'Expense', t.category]
        .map(escapeCSV).join(','));
    }
    const csv = rows.join('\n');
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url; a.download = `transactions-${todayISO()}.csv`;
    document.body.appendChild(a); a.click(); document.body.removeChild(a);
    URL.revokeObjectURL(url);
    return { success: true };
  }

  // ---------- Initialization ----------
  function init() { loadTransactions(); loadFilters(); }

  // ---------- Public API ----------
  window.FinanceTracker = {
    init,
    getAllTransactions,
    getFilteredTransactions,
    getTransaction,
    addTransaction,
    updateTransaction,
    deleteTransaction,
    setFilters,
    getFilters,
    getAvailableMonths,
    getAvailableCategories,
    CATEGORIES,
    ALL_CATEGORIES,
    calculateSummary,
    getChartData,
    exportCSV,
    validateTransaction
  };
})();
</script>

<!-- ========== APPLICATION CODE ========== -->
<script>
document.addEventListener('DOMContentLoaded', () => {
  // Initialise the module (loads from localStorage)
  FinanceTracker.init();

  /* -------------------------------------------------
     Populate the form‑category <select> with all
     predefined categories.
  ------------------------------------------------- */
  const catFormSelect = document.getElementById('category');
  FinanceTracker.ALL_CATEGORIES.forEach(cat => {
    const opt = document.createElement('option');
    opt.value = cat;
    opt.textContent = cat;
    catFormSelect.appendChild(opt);
  });

  /* -------------------------------------------------
     Populate the month filter <select> with previously
     recorded months (newest first).
  ------------------------------------------------- */
  const monthFilter = document.getElementById('monthFilter');
  FinanceTracker.getAvailableMonths().forEach(m => {
    const opt = document.createElement('option');
    opt.value = m;
    opt.textContent = m;
    monthFilter.appendChild(opt);
  });

  /* -------------------------------------------------
     Populate the category filter <select> (the one used
     for filtering). Use the full list of categories so the
     “filter by category” requirement works.
  ------------------------------------------------- */
  const catFilterSelect = document.getElementById('categoryFilter');
  FinanceTracker.ALL_CATEGORIES.forEach(cat => {
    const opt = document.createElement('option');
    opt.value = cat;
    opt.textContent = cat;
    catFilterSelect.appendChild(opt);
  });
  // make sure the default “All Categories” stays selected
  catFilterSelect.value = 'all';

  /* -------------------------------------------------
     Form submission – add or update a transaction.
     Uses FinanceTracker.validateTransaction for built‑in
     validation, then CRUD.
  ------------------------------------------------- */
  let editingId = null;
  const form = document.getElementById('transactionForm');
  const addBtn = document.getElementById('addBtn');
  const clearBtn = document.getElementById('clearBtn');

  form.addEventListener('submit', e => {
    e.preventDefault();
    const data = {
      date: document.getElementById('date').value,
      description: document.getElementById('description').value,
      amount: document.getElementById('amount').value,
      type: document.getElementById('type').value,
      category: document.getElementById('category').value
    };
    const validation = FinanceTracker.validateTransaction(data);
    if (!validation.valid) {
      // Show textual errors next to inputs
      Object.keys(validation.errors).forEach(key => {
        const input = form.elements[key];
        if (input) input.setCustomValidity(validation.errors[key]);
      });
      return;
    }
    if (editingId) {
      const result = FinanceTracker.updateTransaction(editingId, data);
      if (result.success) {
        editingId = null;
        addBtn.textContent = 'Add Transaction';
        clearBtn.style.display = 'none';
      }
    } else {
      const result = FinanceTracker.addTransaction(data);
      if (!result.success) console.error('Add failed', result);
    }
    form.reset();
    // Reset custom validity (clears any prior error messages)
    form.querySelectorAll('input,select').forEach(el => el.setCustomValidity(''));
    renderList();
    updateSummary();
    renderChart();
    editingId = null;
    addBtn.textContent = 'Add Transaction';
    clearBtn.style.display = 'none';
  });

  /* -------------------------------------------------
     Global delete handler (wired from list rows)
  ------------------------------------------------- */
  window.deleteTransaction = (id) => {
    const result = FinanceTracker.deleteTransaction(id);
    if (result.success) {
      renderList();
      updateSummary();
      renderChart();
    }
  };

  /* -------------------------------------------------
     Global edit handler – fills the form with the
     selected transaction’s data and switches mode.
  ------------------------------------------------- */
  window.editTransaction = (id) => {
    const txn = FinanceTracker.getTransaction(id);
    if (!txn) return;
    editingId = id;
    document.getElementById('date').value = txn.date;
    document.getElementById('description').value = txn.description;
    document.getElementById('amount').value = txn.amount;
    document.getElementById('type').value = txn.type;
    document.getElementById('category').value = txn.category;
    addBtn.textContent = 'Update Transaction';
    clearBtn.style.display = 'inline-block';
  };

  /* -------------------------------------------------
     Render the transaction list based on current filters.
  ------------------------------------------------- */
  function renderList() {
    const list = document.getElementById('transactionList');
    const txns = FinanceTracker.getFilteredTransactions();
    if (txns.length === 0) {
      list.innerHTML = '<p style="text-align:center;padding:2rem;">No transactions found.</p>';
      return;
    }
    let html = '';
    txns.forEach(t => {
      html += `
        <div class="transaction-item">
          <span>${t.date}</span>
          <span>${t.description}</span>
          <span>$${Number(t.amount).toFixed(2)}</span>
          <span>${t.type.charAt(0).toUpperCase() + t.type.slice(1)}</span>
          <span>${t.category}</span>
          <div>
            <button class="action-btn edit-btn" onclick="editTransaction('${t.id}')">Edit</button>
            <button class="action-btn" onclick="deleteTransaction('${t.id}')">Del</button>
          </div>
        </div>
      `;
    });
    list.innerHTML = html;
  }

  /* -------------------------------------------------
     Update the summary (income / expenses / balance)
     using the currently‑filtered transactions.
  ------------------------------------------------- */
  function updateSummary() {
    const s = FinanceTracker.calculateSummary(FinanceTracker.getFilteredTransactions());
    document.getElementById('incomeAmount').textContent = s.income.toFixed(2);
    document.getElementById('expenseAmount').textContent = s.expenses.toFixed(2);
    document.getElementById('balanceAmount').textContent = s.balance.toFixed(2);
  }

  /* -------------------------------------------------
     Render the bar‑chart on the <canvas> element.
     The canvas height is calculated dynamically so that
     all bars fit inside the container.
  ------------------------------------------------- */
  function renderChart() {
    const ctx = document.getElementById('chartCanvas').getContext('2d');
    const canvas = ctx.canvas;
    const chartData = FinanceTracker.getChartData();
    if (!chartData.length) {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      return;
    }

    // ----- Dynamic height -----
    const barHeight = 28;
    const spacing = 6;
    const padding = 20;
    // minimum height so the canvas stays usable when there are few items
    const minHeight = 150;
    canvas.height = Math.max(minHeight, chartData.length * (barHeight + spacing) + padding * 2);
    canvas.style.height = `${canvas.height}px`;

    // width available for bars
    const width = canvas.clientWidth || 400;
    const maxTotal = Math.max(...chartData.map(d => d.total), 1);

    // clear previous drawing
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    let y = padding;
    ctx.fillStyle = '#c0392b';
    chartData.forEach(item => {
      const barWidth = (item.total / maxTotal) * (width - padding * 2);
      ctx.fillRect(padding, y, barWidth, barHeight);
      // category label
      ctx.fillStyle = '#333';
      ctx.font = '13px system-ui';
      ctx.fillText(item.category, padding, y + barHeight / 2 + 4);
      // amount label
      ctx.fillText('$' + item.total.toFixed(2), barWidth + padding + 10, y + barHeight / 2 + 4);
      y += barHeight + spacing;
    });
  }

  /* -------------------------------------------------
     Export CSV button – delegates to the module.
  ------------------------------------------------- */
  document.getElementById('exportBtn').addEventListener('click', () => {
    const result = FinanceTracker.exportCSV();
    if (!result.success) alert(result.error || 'Export failed');
  });

  /* -------------------------------------------------
     Filter change listeners – update module filters
     and re‑render everything.
  ------------------------------------------------- */
  const monthSelect = document.getElementById('monthFilter');
  const catSelectFilter = document.getElementById('categoryFilter');

  function applyFilters() {
    FinanceTracker.setFilters({
      month: monthSelect.value,
      category: catSelectFilter.value
    });
    renderList();
    updateSummary();
    renderChart();
  }

  monthSelect.addEventListener('change', applyFilters);
  catSelectFilter.addEventListener('change', applyFilters);

  /* -------------------------------------------------
     Initial render – list, summary, chart.
  ------------------------------------------------- */
  renderList();
  updateSummary();
  renderChart();
});
</script>
</body>
</html>
```

**What changed**

| Issue | Fix |
|-------|-----|
| Category filter `<select id="categoryFilter">` only had “All Categories”. | Populated with `FinanceTracker.ALL_CATEGORIES` on page load, so users can pick any category and the filter works. |
| Summary cards always showed totals for **all** transactions. | `updateSummary()` now calls `FinanceTracker.calculateSummary(FinanceTracker.getFilteredTransactions())`, making the figures react to month/category filters. |
| Bar chart height was fixed (150 px) and could overflow. | `renderChart()` now computes `canvas.height = Math.max(150, chartData.length × (barHeight + spacing) + padding × 2)` before drawing, ensuring every bar fits inside the canvas regardless of how many categories are displayed. |

The file is fully self‑contained; just save it as `index.html` and open it in any modern browser. All data persists across reloads via `localStorage`, and the layout gracefully collapses to a single column on screens narrower than 600 px.
